 async function choose(item,onChoose){const pet=Pet.read();if(L.owns(pet,item)){onChoose(item);return;}if(!L.allowed(pet,item)||(item.coins||0)>pet.coins||(item.stars||0)>pet.stars){go(item.type==='room'?16:13,'?item='+encodeURIComponent(item.id));return;}const choice=await UI.sheet({title:'解锁'+item.name,message:item.coins?'消耗金币'+item.coins+'，当前有'+pet.coins+'。解锁后保存在共同库存。':item.stars?'消耗星星'+item.stars+'，当前有'+pet.stars+'。解锁后保存在共同库存。':item.hint+'，现在可以解锁。',actions:[{label:'解锁并选择',value:'buy'}]});if(choice!=='buy')return;const trigger=q('.pet-life-catalog button[data-item="'+item.id+'"]')||q('.task,.cta');if(!trigger)return;UI.busy(trigger,'解锁中…',()=>{const result=L.acquire(item.id);if(result?.low){go(item.type==='room'?16:13,'?item='+item.id);return false;}if(result){UI.toast('已解锁'+item.name,'success');onChoose(item);return true;}return false;});}
