  if(n===12){let group='配饰',selected=pet.outfit||null;const preview=button('',()=>{},'pet-life-preview');preview.disabled=true;const guard=UI.guard(screen,{fallback:'m07-p03.html',value:()=>selected});paint=()=>{const current=Pet.read();text('.affinity strong',current.affinity);text('.trials','金币 '+current.coins+' · 星星 '+current.stars);text('.closet-name',current.name+'的小衣橱');text('.note','试穿是预览，保存后才更新共同穿戴');preview.textContent='预览：'+(selected||'不佩戴');all('.tabs button').forEach(b=>b.setAttribute('aria-selected',String(b.textContent===group)));const list=q('.item-list');catalogButtons(list,L.catalog.filter(v=>v.type==='outfit'&&v.group===group),selected,item=>{selected=item.name;paint();});const none=document.createElement('button');none.type='button';none.textContent='不佩戴';none.setAttribute('aria-pressed',String(!selected));none.onclick=()=>{selected=null;paint();};list.prepend(none);};all('.tabs button').forEach(b=>b.onclick=()=>{group=b.textContent;paint();});bind('#save',()=>UI.busy(q('#save'),'保存穿戴中…',()=>{if(!L.equip(selected))return false;guard.commit();UI.toast('穿戴已保存','success');paint();return true;}));paint();return;}
