  if(n===18){all('.entry,.byline,.adoption-note').forEach(e=>e.hidden=true);text('.summary','我们一起照顾的第 '+Pet.days(pet)+' 天');text('.next','成长故事来自真实照顾，也可以亲手写一页');const list=document.createElement('section');list.className='pet-life-story-list';list.setAttribute('aria-label','成长时间线');screen.append(list);paint=()=>{list.replaceChildren();const rows=L.stories(Pet.read());if(!rows.length){const h=document.createElement('h2'),copy=document.createElement('p');h.textContent='第一段故事还在等你';copy.textContent='照顾它或写下一页，让回忆从今天开始。';list.append(h,copy);}for(const entry of rows){const b=document.createElement('button'),meta=document.createElement('small'),title=document.createElement('strong');b.type='button';meta.textContent=entry.date+' · '+entry.actor;title.textContent=entry.text.length>80?entry.text.slice(0,80)+'…':entry.text;b.append(meta,title);b.onclick=()=>go(entry.blocked?17:19,'?id='+encodeURIComponent(entry.id));list.append(b);}};text('.view','写一页成长故事');bind('.view',()=>writeStory(paint));button('关联共同记录',async()=>{const rows=L.sources();if(!rows.length){const result=await UI.sheet({title:'还没有共同记录',message:'先发布一篇共同日记或照片，再收进宠物故事。',actions:[{label:'写共同日记',value:'diary'}]});if(result==='diary')UI.go('m03-p05.html');return;}const id=await UI.sheet({title:'关联共同记录',actions:rows.map(v=>({label:v.title,value:{id:v.id,kind:v.kind}}))});if(!id)return;const trigger=q('.pet-life-extra');UI.busy(trigger,'关联中…',()=>{if(!L.link(id.id,id.kind))return false;UI.toast('共同记录已关联','success');paint();return true;});});paint();return;}
  if(n===17||n===19){const entry=pet.logs.find(v=>v.id===(params.get('id')||L.stories(pet)[0]?.id)),view=L.story(entry);if(!view){go(18);return;}if((n===17)!==view.blocked){go(view.blocked?17:19,'?id='+encodeURIComponent(entry.id));return;}if(n===17){q('.back').setAttribute('aria-label','返回成长时间线');q('.back').lastChild.textContent='成长时间线';text('.return','返回成长时间线');text('.first-title','关联的共同记录');text('.date',entry.date);text('.first-copy','原有成长记录已保留，关联内容需要仍为共同可见。');text('.reason','关联记录已删除或不可见，请返回成长时间线');bind('.return',()=>go(18));return;}paint=()=>{const current=Pet.read(),updated=L.story(current.logs.find(v=>v.id===entry.id));if(updated.blocked){go(17,'?id='+entry.id);return;}text('.title',entry.date+' · 成长故事');text('.note',updated.sourceId?updated.text+'\n'+updated.body:updated.text);if(updated.url){const link=document.createElement('button');link.type='button';link.className='pet-life-inline-source';link.textContent='查看关联记录';link.onclick=()=>UI.go(updated.url);q('.note').prepend(link);}text('.name.her',entry.actor);text('.role.her',entry.type==='note'?'写下这页故事':entry.type==='source'?'关联这段记录':'留下照顾记录');q('.note').tabIndex=0;q('.note').setAttribute('role','region');q('.note').setAttribute('aria-label','成长故事正文');q('.reply').tabIndex=0;q('.reply').setAttribute('role','region');q('.reply').setAttribute('aria-label','共同回应');text('.name.his','共同回应');text('.role.his',(updated.comments||[]).length+' 条回应');text('.reply',(updated.comments||[]).map(v=>v.author+'：'+v.text).join('\n')||'还没有回应，一起留下温柔的一句话吧');};text('.next','写下今天的下一页');bind('.next',()=>writeStory(()=>go(18)));const respond=button('回应这一页',()=>edit({title:'回应',label:'回应内容',limit:300,save:text=>L.reply(entry.id,text),after:paint}));respond.disabled=!P.privacy().replies;paint();return;}
  if(n===20){text('.back','返回');let id=params.get('achievement')||'days30';paint=()=>{const current=Pet.read(),items=L.achievements(current),item=items.find(v=>v.id===id);if(!item){go(21);return;}text('.milestone',item.name);text('.congrats',item.done?'恭喜达成！':'我们正在一起成长');text('.reward','星星 ×'+item.reward);text('.count','已达成 '+items.filter(v=>v.done).length+' / '+items.length);text('.stamp',item.done?'已达成':'进行中');const claim=q('.claim');claim.textContent=item.claimed?'奖励已领取':item.done?'领取奖励':'进度 '+Math.min(item.progress,item.target)+' / '+item.target;claim.disabled=item.claimed||!item.done;for(const[row,v]of all('.row').map((row,index)=>[row,items[index]]))row.textContent=v.name+'　'+Math.min(v.progress,v.target)+' / '+v.target;};bind('.claim',()=>UI.busy(q('.claim'),'领取中…',()=>{if(!L.achievementClaim(id))return false;UI.toast('成就奖励已到账','success');return true;}).then(paint));paint();return;}
  if(n===21){all('.days,.next').forEach(e=>e.hidden=true);paint=()=>{const current=Pet.read(),items=L.achievements(current);text('.badge-number',items.filter(v=>v.done).length+' / '+items.length);const cards=q('.cards');cards.classList.add('pet-life-catalog','pet-life-achievements');cards.replaceChildren();for(const item of items){const b=document.createElement('button');b.type='button';b.textContent=item.name+' '+(item.claimed?'奖励已领取':item.done?'可领取奖励':Math.min(item.progress,item.target)+' / '+item.target);b.onclick=()=>go(20,'?achievement='+item.id);cards.append(b);}};bind('.cta',()=>go(11));button('收藏图鉴',()=>go(22));paint();return;}
  if(n===22){let group='装扮';paint=()=>{const current=Pet.read(),items=L.catalog.filter(v=>v.type===(group==='装扮'?'outfit':'room')),badges=L.achievements(current),total=L.catalog.length+badges.length;const owned=L.catalog.filter(v=>L.owns(current,v)).length+badges.filter(v=>v.claimed).length;text('.count','已收藏 '+owned+' / '+total);text('.next','收藏来自共同照顾，未解锁物品可查看条件');all('.tabs button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===group)));const cards=q('.cards');cards.classList.add('pet-life-catalog');cards.replaceChildren();for(const item of group==='纪念物'?badges:items){const b=document.createElement('button');b.type='button';b.textContent=item.name+' '+(group==='纪念物'?item.claimed?'已拥有':item.done?'待领取':'待达成':L.label(current,item));b.onclick=()=>go(23,'?'+(group==='纪念物'?'achievement=':'item=')+item.id);cards.append(b);}};all('.tabs button').forEach(b=>b.onclick=()=>{group=b.dataset.tab;paint();});button('认识小伙伴',async()=>{const kind=await UI.sheet({title:'四位小伙伴',message:'首期共同选择一位。当前小伙伴会保留，不会直接切换或覆盖已有成长。',actions:['小狗','小猫','小兔','小狐狸'].map(kind=>({label:kind+(Pet.read().kind===kind?' · 正在共同照顾':' · 首次领养可选'),value:kind}))});if(!kind)return;const picture=document.createElement('div');picture.className='pet-breed-picture';picture.dataset.kind=kind;picture.setAttribute('role','img');picture.setAttribute('aria-label',kind+'领养插画');await UI.modal({title:kind+' · '+(Pet.read().kind===kind?'已共同领养':'尚未领养'),message:'领养时可以选择品种和名字。这里用于了解伙伴，不会切换或覆盖已有宠物与成长记录。',content:picture,confirm:'了解了',cancel:'关闭'});});paint();return;}
