 async function load(){let status=q('.pet-load');if(!status){status=document.createElement('section');status.className='pet-load';status.setAttribute('role','status');screen.append(status);}status.replaceChildren();status.append(UI.components.loading({mode:'skeleton',label:'正在打开宠物的共同回忆…'}));screen.setAttribute('aria-busy','true');await new Promise(resolve=>setTimeout(resolve,400));screen.setAttribute('aria-busy','false');try{if(UI.failNext('pet-life-load'))throw new Error('宠物记录暂时打不开');status.remove();render();}catch(error){if(!status.isConnected)screen.append(status);status.textContent=error.message;const retry=document.createElement('button');retry.textContent='重新加载';retry.onclick=load;status.append(retry);}}
